<?php
/**
 * Farkas Klára preview — login gate core (shared by login.php / auth-check.php).
 *
 * auth-config.php is GENERATED by scripts/deploy-pspro.mjs on every deploy:
 * base path, PBKDF2 password hash (never the password), a random signing
 * secret. A new deploy rotates the secret → everyone logs in again.
 */
declare(strict_types=1);

$config = require __DIR__ . '/auth-config.php';

const FK_COOKIE = 'fk_preview';

function fk_base(): string {
    global $config;
    return $config['base'];
}

function fk_password_ok(string $user, string $password): bool {
    global $config;
    if (!hash_equals($config['user'], $user)) return false;
    $hash = hash_pbkdf2('sha256', $password, base64_decode($config['salt']), $config['iterations'], 32, true);
    return hash_equals(base64_decode($config['hash']), $hash);
}

/** Signed token: "<expiry>.<hmac(expiry)>". */
function fk_issue_token(): void {
    global $config;
    $expires = time() + $config['ttl'];
    $token = $expires . '.' . hash_hmac('sha256', 'fk|' . $expires, $config['secret']);
    setcookie(FK_COOKIE, $token, [
        'expires' => $expires,
        'path' => fk_base(),
        'secure' => true,
        'httponly' => true,
        'samesite' => 'Lax',
    ]);
}

function fk_token_ok(): bool {
    global $config;
    $token = $_COOKIE[FK_COOKIE] ?? '';
    if (!preg_match('/^(\d{10})\.([a-f0-9]{64})$/', $token, $m)) return false;
    if ((int) $m[1] < time()) return false;
    return hash_equals(hash_hmac('sha256', 'fk|' . $m[1], $config['secret']), $m[2]);
}

function fk_clear_token(): void {
    setcookie(FK_COOKIE, '', ['expires' => time() - 3600, 'path' => fk_base(), 'secure' => true, 'httponly' => true, 'samesite' => 'Lax']);
}

/** Preview pages must never be indexed or cached by shared caches. */
function fk_private_headers(): void {
    header('X-Robots-Tag: noindex, nofollow');
    header('Cache-Control: private, no-store');
}
